cat > src/game/core.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { activateCard, advanceGame, createGame, isWon } from './core.ts';
function game() { const g = createGame('np1-4-1'); if (!g) throw new Error('missing game'); return g; }
describe('game rules', () => {
  it('matches the independent documented shuffle vector', () => { expect(game().deck).toEqual([6,7,0,5,2,2,0,5,3,7,1,6,4,4,1,3]); });
  it('counts valid turns and waits 800 active milliseconds for a mismatch', () => {
    let g = activateCard(game(), 0); g = activateCard(g, 0); expect(g.moves).toBe(0);
    g = activateCard(g, 1); expect(g.moves).toBe(1); expect(activateCard(g, 11)).toBe(g);
    g = advanceGame(g, 799); expect(g.selection.kind).toBe('mismatch');
    g = advanceGame(g, 1); expect(g.selection.kind).toBe('closed');
    g = activateCard(activateCard(g, 0), 11); expect(g.matched).toEqual([0,11]); expect(g.moves).toBe(2);
  });
  it('stops time at victory', () => {
    let g = game();
    for (const [a,b] of [[0,11],[1,9],[2,6],[3,7],[4,5],[8,15],[10,14],[12,13]]) { if (a === undefined || b === undefined) throw new Error(); g = activateCard(activateCard(g,a),b); }
    expect(isWon(g)).toBe(true); expect(advanceGame(g, 1000).elapsedMs).toBe(0);
  });
});
EOF
cat > src/game/formats.test.ts <<'EOF'
import { expect, it } from 'vitest';
import { decodeSnapshot, encodeSnapshot, replayGame } from './formats.ts';
it('round trips the documented snapshot and rejects inconsistent or extra data', () => {
  const text = '{"version":1,"boardCode":"np1-4-1","matched":[0,11],"selection":{"kind":"mismatch","first":1,"second":2,"remainingMs":300},"moves":2,"elapsedMs":1500,"started":true}';
  const game = decodeSnapshot(text); expect(game).not.toBeNull(); if (!game) throw new Error();
  expect(decodeSnapshot(encodeSnapshot(game))).toEqual(game);
  expect(decodeSnapshot(text.replace('"moves":2','"moves":1'))).toBeNull();
  expect(decodeSnapshot(text.replace('"version":1','"extra":0,"version":1'))).toBeNull();
});
it('resolves a mismatch before an action at its exact deadline', () => {
  const game = replayGame(JSON.stringify({version:1,boardCode:'np1-4-1',actions:[{atMs:0,index:0},{atMs:0,index:1},{atMs:800,index:2}],endMs:800}));
  expect(game?.selection).toEqual({kind:'one',index:2}); expect(game?.elapsedMs).toBe(800);
  expect(replayGame('{"version":1}')).toBeNull();
});
EOF
cat > playwright.config.ts <<'EOF'
import { defineConfig } from '@playwright/test';
export default defineConfig({ testDir: './tests', use: { browserName: 'chromium', baseURL: 'http://127.0.0.1:4173' }, webServer: { command: 'npx vite preview --host 127.0.0.1 --port 4173', url: 'http://127.0.0.1:4173', reuseExistingServer: false } });
EOF
cat > tests/game.spec.ts <<'EOF'
import { test, expect } from '@playwright/test';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
test('offline file supports a keyboard game and reproduction', async ({ page, context }) => {
  await context.route('**/*', route => route.abort());
  await page.goto(pathToFileURL(resolve('dist/index.html')).href);
  await expect(page.getByRole('heading', { name: 'Neon Pairs.' })).toBeVisible();
  await page.getByText('Reproduce a game').click();
  await page.getByLabel('Board code').fill('np1-4-1'); await page.getByRole('button',{name:'Load board'}).click();
  const cards = page.locator('.card'); await expect(cards).toHaveCount(16);
  await expect(cards.nth(0)).toHaveAccessibleName('Row 1, column 1, closed');
  await cards.nth(0).focus(); await page.keyboard.press('ArrowRight'); await expect(cards.nth(1)).toBeFocused();
  for (const [a,b] of [[0,11],[1,9],[2,6],[3,7],[4,5],[8,15],[10,14],[12,13]]) { if (a === undefined || b === undefined) throw new Error(); await cards.nth(a).click(); await cards.nth(b).click(); }
  await expect(page.getByText('All pairs found!',{exact:true})).toBeVisible();
  await expect(page.getByText('8 moves and', {exact:false}).first()).toBeVisible();
  await page.getByRole('button',{name:'Export snapshot'}).click(); await expect(page.getByLabel('Snapshot JSON')).toContainText('"version": 1');
});
test('saved size and paused snapshot on HTTP', async ({ page }) => {
  await page.goto('/'); await page.getByLabel('Grid size').selectOption('6'); await page.reload(); await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await page.getByText('Reproduce a game').click();
  await page.getByLabel('Snapshot JSON').fill('{"version":1,"boardCode":"np1-4-1","matched":[0,11],"selection":{"kind":"mismatch","first":1,"second":2,"remainingMs":300},"moves":2,"elapsedMs":1500,"started":true}');
  await page.getByRole('button',{name:'Load snapshot'}).click(); await expect(page.getByText('Loaded snapshot. Select Resume to continue.').first()).toBeVisible();
  await page.waitForTimeout(400); await expect(page.locator('.card.revealed')).toHaveCount(4);
  await page.getByRole('button',{name:'Resume'}).click(); await expect(page.locator('.card.revealed')).toHaveCount(2);
});
EOF
npm ci --no-audit --no-fund",workdir:"/work",yield_time_ms:1000,max_output_tokens:2000}); text(JSON.stringify(r));

